package vn.cineprime.admin;

import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.stream.Collectors;
import org.springframework.http.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import vn.cineprime.auth.SecurityConfig.SessionUser;
import vn.cineprime.booking.BookingService;
import vn.cineprime.domain.Store;
import vn.cineprime.media.MediaService;
import vn.cineprime.payment.MomoService;
import vn.cineprime.web.Catalog;
import static vn.cineprime.domain.Domain.*;

@Controller @RequestMapping("/admin")
public class AdminController {
    private final Store db;private final AdminService admin;private final Catalog catalog;private final BookingService bookings;private final MomoService momo;private final MediaService media;private final Clock clock;
    public AdminController(Store db,AdminService admin,Catalog catalog,BookingService bookings,MomoService momo,MediaService media,Clock clock){this.db=db;this.admin=admin;this.catalog=catalog;this.bookings=bookings;this.momo=momo;this.media=media;this.clock=clock;}
    @ModelAttribute public void nav(Model model){model.addAttribute("adminMenu",AdminService.RESOURCES.entrySet().stream().map(e->Map.of("key",e.getKey(),"label",e.getValue().label())).toList());}
    @org.springframework.transaction.annotation.Transactional(readOnly=true)
    @GetMapping public String dashboard(@RequestParam(defaultValue="month")String period,@RequestParam(required=false)LocalDate date,Model model){
        LocalDate today=date==null?LocalDate.now(clock.withZone(ZoneId.of("Asia/Ho_Chi_Minh"))):date;
        LocalDate from=switch(period){case "day"->today;case "week"->today.minusDays(today.getDayOfWeek().getValue()-1);case "year"->today.withDayOfYear(1);default->today.withDayOfMonth(1);};
        LocalDate until=switch(period){case "day"->from.plusDays(1);case "week"->from.plusWeeks(1);case "year"->from.plusYears(1);default->from.plusMonths(1);};ZoneId zone=ZoneId.of("Asia/Ho_Chi_Minh");
        List<Order> paid=db.list(Order.class,"where e.status='PAID' and e.paidAt>=?1 and e.paidAt<?2",from.atStartOfDay(zone).toInstant(),until.atStartOfDay(zone).toInstant());
        long revenue=paid.stream().mapToLong(o->o.total).sum();
        long tickets=db.query("select count(s) from %s s, %s o where s.orderId=o.id and o.status='PAID' and o.paidAt>=?1 and o.paidAt<?2".formatted(db.entityName(OrderSeat.class),db.entityName(Order.class)),Long.class,from.atStartOfDay(zone).toInstant(),until.atStartOfDay(zone).toInstant()).getFirst();
        model.addAttribute("revenue",db.money(revenue));model.addAttribute("ticketCount",tickets);model.addAttribute("orderCount",paid.size());model.addAttribute("customerCount",db.count(User.class,"where e.role='CUSTOMER'"));model.addAttribute("nowCount",db.count(Movie.class,"where e.active=true and e.status='NOW_SHOWING'"));model.addAttribute("comingCount",db.count(Movie.class,"where e.active=true and e.status='COMING_SOON'"));model.addAttribute("period",period);model.addAttribute("reportDate",today);model.addAttribute("range",from+" → "+until);
        Map<String,Long> byDate=new TreeMap<>();for(Order o:paid)byDate.merge(o.paidAt.atZone(zone).toLocalDate().toString(),o.total,Long::sum);long max=byDate.values().stream().mapToLong(Long::longValue).max().orElse(1);model.addAttribute("chart",byDate.entrySet().stream().map(e->Map.of("label",e.getKey(),"amount",db.money(e.getValue()),"width",Math.max(1,e.getValue()*100/Math.max(1,max)))).toList());
        Map<String,Long> byMovie=new HashMap<>();paid.forEach(o->byMovie.merge(o.movieTitle,o.total,Long::sum));model.addAttribute("topMovies",byMovie.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(10).map(e->Map.of("title",e.getKey(),"amount",db.money(e.getValue()))).toList());
        Instant rangeStart=from.atStartOfDay(zone).toInstant(),rangeEnd=until.atStartOfDay(zone).toInstant();
        Map<Long,Long> capacities=new HashMap<>(),sales=new HashMap<>();
        db.query("select i.showtimeId,count(i) from %s i, %s seat, %s s where i.seatId=seat.id and seat.active=true and i.showtimeId=s.id and s.startsAt>=?1 and s.startsAt<?2 and s.status<>'CANCELLED' group by i.showtimeId".formatted(db.entityName(Inventory.class),db.entityName(Seat.class),db.entityName(Showtime.class)),Object[].class,rangeStart,rangeEnd).forEach(row->capacities.put((Long)row[0],(Long)row[1]));
        db.query("select t.showtimeId,count(t) from %s t, %s s where t.showtimeId=s.id and s.startsAt>=?1 and s.startsAt<?2 and s.status<>'CANCELLED' group by t.showtimeId".formatted(db.entityName(Ticket.class),db.entityName(Showtime.class)),Object[].class,rangeStart,rangeEnd).forEach(row->sales.put((Long)row[0],(Long)row[1]));
        model.addAttribute("occupancy",db.list(Showtime.class,"where e.startsAt>=?1 and e.startsAt<?2 and e.status<>'CANCELLED' order by e.startsAt",rangeStart,rangeEnd).stream().map(s->{Map<String,Object> v=catalog.show(s);long capacity=capacities.getOrDefault(s.id,0L),sold=sales.getOrDefault(s.id,0L);v.put("occupancy",sold+" / "+capacity+" ("+(capacity==0?0:sold*100/capacity)+"%)");return v;}).toList());
        model.addAttribute("reconciliation",db.views(db.list(Payment.class,"where e.reconciliation=true order by e.id desc")));return "admin/dashboard";
    }
    @GetMapping("/manage/{key}") public String list(@PathVariable String key,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,Model model){AdminService.Resource r=admin.resource(key);List<? extends Row> matching=db.list(r.type(),"order by e.id desc").stream().filter(row->db.view(row).values().toString().toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))).toList();model.addAttribute("key",key);model.addAttribute("resourceLabel",r.label());model.addAttribute("q",q);model.addAttribute("page",Math.max(0,page));model.addAttribute("hasMore",matching.size()>(Math.max(0,page)+1)*50);model.addAttribute("rows",matching.stream().skip(Math.max(0,page)*50L).limit(50).map(row->{Map<String,Object> v=db.view(row);v.put("summary",summary(row));return v;}).toList());return "admin/list";}
    private String summary(Row row){Map<String,Object> view=db.view(row);String text=view.entrySet().stream().filter(e->!Set.of("id","description","body","poster","banner","image","trailer").contains(e.getKey())).map(e->label(e.getKey())+": "+Objects.toString(e.getValue(),"—")).collect(Collectors.joining(" · "));if(row instanceof Room r)text+=" · Sức chứa: "+db.list(Seat.class,"where e.roomId=?1 and e.active=true",r.id).size();return text;}
    @GetMapping("/manage/{key}/edit") public String edit(@PathVariable String key,@RequestParam(required=false)Long id,Model model)throws Exception{
        AdminService.Resource r=admin.resource(key);Row row=id==null?r.type().getConstructor().newInstance():db.get(r.type(),id);List<Map<String,Object>> fields=new ArrayList<>();
        for(String name:r.fields().split(",")){Field f=r.type().getField(name);Object value=f.get(row);Map<String,Object> input=new HashMap<>();input.put("name",name);input.put("label",label(name));input.put("value",value instanceof Instant t?db.local(t):Objects.toString(value,""));String type=f.getType()==boolean.class?"checkbox":f.getType()==Instant.class?"datetime-local":f.getType()==LocalDate.class?"date":f.getType()==long.class||f.getType()==int.class?"number":Set.of("body","description","comment","biography").contains(name)?"textarea":"text";input.put("type",type);input.put("checked",Boolean.TRUE.equals(value));List<Map<String,Object>> options=options(key,name);input.put("options",options);fields.add(input);}
        model.addAttribute("fields",fields);model.addAttribute("key",key);model.addAttribute("resourceLabel",r.label());model.addAttribute("rowId",id);return "admin/edit";
    }
    private String label(String name){return Map.ofEntries(Map.entry("movieId","Phim"),Map.entry("cinemaId","Rạp"),Map.entry("roomId","Phòng"),Map.entry("genreId","Thể loại"),Map.entry("personId","Diễn viên / Đạo diễn"),Map.entry("fromMinute","Phút bắt đầu (0–1439)"),Map.entry("toMinute","Phút kết thúc (1–1440)"),Map.entry("startsAt","Bắt đầu (giờ Việt Nam)"),Map.entry("endsAt","Kết thúc (giờ Việt Nam)"),Map.entry("seatType","Loại ghế (giá theo một ghế vật lý)"),Map.entry("coupleGroup","Mã cặp ghế đôi"),Map.entry("position","Vị trí cột"),Map.entry("rowLabel","Tên hàng"),Map.entry("active","Đang hoạt động"),Map.entry("enabled","Tài khoản hoạt động"),Map.entry("featured","Phim nổi bật")).getOrDefault(name,name);}
    private List<Map<String,Object>> options(String key,String name){
        Class<? extends Row> ref=switch(name){case "movieId"->Movie.class;case "cinemaId"->Cinema.class;case "roomId"->Room.class;case "genreId"->Genre.class;case "personId"->Person.class;default->null;};
        if(ref!=null)return db.list(ref,"order by e.id").stream().map(r->{Map<String,Object> v=new HashMap<>();v.put("value",r.id.toString());Map<String,Object> data=db.view(r);v.put("label","#"+r.id+" · "+data.getOrDefault("title",data.getOrDefault("name","")));return v;}).toList();
        String[] values=switch(name){case "role"->new String[]{"CUSTOMER","STAFF","ADMIN"};case "ageRating"->new String[]{"P","K","T13","T16","T18"};case "seatType","type"->new String[]{"STANDARD","VIP","COUPLE"};case "dayType"->new String[]{"WEEKDAY","WEEKEND"};case "status"->key.equals("movies")?new String[]{"COMING_SOON","NOW_SHOWING","STOPPED"}:new String[]{"DRAFT","OPEN","CANCELLED"};case "kind"->switch(key){case "credits"->new String[]{"ACTOR","DIRECTOR"};case "products"->new String[]{"FOOD","DRINK","COMBO"};case "vouchers"->new String[]{"FIXED","PERCENT"};default->new String[]{"BANNER","ARTICLE","OFFER","POLICY","ABOUT","CONTACT","NOTICE"};};default->new String[0];};
        return Arrays.stream(values).map(v->{Map<String,Object> m=new HashMap<>();m.put("value",v);m.put("label",v);return m;}).toList();
    }
    @PostMapping("/manage/{key}/save") public String save(@AuthenticationPrincipal SessionUser u,@PathVariable String key,@RequestParam(required=false)Long id,@RequestParam Map<String,String> values){admin.save(u.id(),key,id,values);return "redirect:/admin/manage/"+key+"?saved";}
    @PostMapping("/manage/{key}/{id}/disable") public String disable(@AuthenticationPrincipal SessionUser u,@PathVariable String key,@PathVariable Long id){admin.remove(u.id(),key,id);return "redirect:/admin/manage/"+key;}
    @PostMapping("/layout") public String layout(@AuthenticationPrincipal SessionUser u,@RequestParam Long roomId,@RequestParam int rows,@RequestParam int columns){admin.generateSeats(u.id(),roomId,rows,columns);return "redirect:/admin/manage/seats";}
    @PostMapping("/upload") public String upload(@RequestParam MultipartFile file,Model model)throws Exception{model.addAttribute("uploaded",media.upload(file,true));return "admin/upload";}
    @GetMapping("/upload") public String upload(){return "admin/upload";}
    @GetMapping("/voucher-usage/{id}") public String voucherUsage(@PathVariable Long id,Model model){Voucher voucher=db.get(Voucher.class,id);List<VoucherUse> uses=db.list(VoucherUse.class,"where e.voucherId=?1 order by e.id desc",id);model.addAttribute("voucher",db.view(voucher));model.addAttribute("used",uses.stream().filter(u->u.status.equals("USED")).count());model.addAttribute("reserved",uses.stream().filter(u->u.status.equals("RESERVED")&&u.expiresAt.isAfter(clock.instant())).count());model.addAttribute("uses",uses.stream().map(u->{Map<String,Object> v=db.view(u);v.put("email",db.get(User.class,u.userId).email);v.put("orderCode",db.get(Order.class,u.orderId).code);v.put("when",db.date(u.expiresAt));return v;}).toList());return "admin/voucher-usage";}
    @GetMapping("/schedule") public String schedule(@RequestParam(required=false)LocalDate date,@RequestParam(required=false)Long cinemaId,Model model){LocalDate day=date==null?LocalDate.now(clock.withZone(ZoneId.of("Asia/Ho_Chi_Minh"))):date;model.addAttribute("day",day);model.addAttribute("schedule",db.list(Showtime.class,"order by e.startsAt").stream().filter(s->s.startsAt.atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalDate().equals(day)).filter(s->cinemaId==null||db.get(Room.class,s.roomId).cinemaId.equals(cinemaId)).map(s->{Map<String,Object> v=catalog.show(s);v.put("ends",db.date(s.endsAt));return v;}).toList());return "admin/schedule";}
    @GetMapping("/layout/{id}") public String layoutPreview(@PathVariable Long id,Model model){Room room=db.get(Room.class,id);model.addAttribute("room",db.view(room));Map<String,List<Map<String,Object>>> rows=new TreeMap<>();for(Seat seat:db.list(Seat.class,"where e.roomId=?1 order by e.rowLabel,e.position",id)){Map<String,Object> v=db.view(seat);v.put("className",seat.type.toLowerCase(Locale.ROOT)+(seat.active?"":" maintenance"));rows.computeIfAbsent(seat.rowLabel,k->new ArrayList<>()).add(v);}model.addAttribute("seatRows",rows.values().stream().map(row->Map.of("label",row.getFirst().get("rowLabel"),"seats",row)).toList());model.addAttribute("busy",admin.busyRoom(id));return "admin/layout-preview";}
    @GetMapping("/orders") public String orders(@RequestParam(defaultValue="")String q,Model model){model.addAttribute("orders",db.list(Order.class,"order by e.createdAt desc").stream().filter(o->(o.code+" "+db.get(User.class,o.userId).email+" "+o.createdAt+" "+o.status).toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))).limit(100).map(catalog::order).toList());model.addAttribute("q",q);return "admin/orders";}
    @GetMapping("/orders/{id}") public String order(@PathVariable Long id,Model model){Order o=db.get(Order.class,id);model.addAttribute("order",catalog.order(o));model.addAttribute("customer",db.view(db.get(User.class,o.userId)));model.addAttribute("lines",db.list(OrderSeat.class,"where e.orderId=?1",id).stream().map(this::summary).toList());model.addAttribute("payments",db.views(db.list(Payment.class,"where e.orderId=?1",id)));model.addAttribute("tickets",db.list(Ticket.class,"where e.orderId=?1",id).stream().map(catalog::ticket).toList());model.addAttribute("combos",db.list(OrderProduct.class,"where e.orderId=?1",id).stream().map(this::summary).toList());return "admin/order";}
    @PostMapping("/orders/{id}/cancel") public String cancel(@AuthenticationPrincipal SessionUser u,@PathVariable Long id){Order o=db.get(Order.class,id);bookings.cancel(o.userId,id);db.audit(u.id(),"ADMIN_CANCEL",o.code);return "redirect:/admin/orders/"+id;}
    @PostMapping("/payments/{id}/verify") public String verify(@AuthenticationPrincipal SessionUser u,@PathVariable Long id){momo.query(id);db.audit(u.id(),"VERIFY_PAYMENT",id.toString());return "redirect:/admin/orders/"+db.get(Payment.class,id).orderId;}
    @GetMapping("/audit") public String audit(Model model){model.addAttribute("logs",db.list(Audit.class,"order by e.createdAt desc").stream().limit(200).map(a->{Map<String,Object> v=db.view(a);v.put("when",db.date(a.createdAt));return v;}).toList());return "admin/audit";}
    private String csv(Object raw){String value=Objects.toString(raw,"");if(value.matches("^[=+@\\-\\t\\r].*"))value="'"+value;return "\""+value.replace("\"","\"\"")+"\"";}
    @GetMapping("/transactions.csv") public ResponseEntity<byte[]> csv(){StringBuilder out=new StringBuilder("\uFEFFĐơn,Email,Ngày đặt,Trạng thái đơn,Thành tiền,Giao dịch,Trạng thái thanh toán,Đối soát\r\n");for(Order o:db.list(Order.class,"order by e.id desc")){List<Payment> ps=db.list(Payment.class,"where e.orderId=?1",o.id);if(ps.isEmpty())out.append(String.join(",",csv(o.code),csv(db.get(User.class,o.userId).email),csv(db.date(o.createdAt)),csv(o.status),csv(o.total),"\"\"","\"\"","\"\"")).append("\r\n");for(Payment p:ps)out.append(String.join(",",csv(o.code),csv(db.get(User.class,o.userId).email),csv(db.date(o.createdAt)),csv(o.status),csv(o.total),csv(p.externalOrderId),csv(p.status),csv(p.reconciliation))).append("\r\n");}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=cineprime-transactions.csv").contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).body(out.toString().getBytes(StandardCharsets.UTF_8));}
}
